_FALLBACK_SRC = '# Action format: [(from_node, to_node, count), ...]\n# "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# "profit_p = revenue_p - upkeep_p"\n# Ownership persists without a garrison. Capture needs two consecutive strict\n# majorities. This conservative strategy uses single-unit capture expeditions,\n# avoids visible opposition, and brings surplus units home.\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef preprocess_map(obs):\n    n = int(obs["n_nodes"])\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    for u, v, length in obs.get("edges", []):\n        u, v, length = int(u), int(v), int(length)\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n        lengths[u, v] = length\n        lengths[v, u] = length\n    for row in adjacency:\n        row.sort()\n\n    distance = [[10**6] * n for _ in range(n)]\n    hop = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n        for v in adjacency[u]:\n            distance[u][v] = lengths[u, v]\n    for k in range(n):\n        for u in range(n):\n            for v in range(n):\n                candidate = distance[u][k] + distance[k][v]\n                if candidate < distance[u][v]:\n                    distance[u][v] = candidate\n    for u in range(n):\n        for v in range(n):\n            if u != v:\n                for w in adjacency[u]:\n                    if lengths[u, w] + distance[w][v] == distance[u][v]:\n                        hop[u][v] = w\n                        break\n    return adjacency, lengths, distance, hop\n\n\ndef payout(node_value, owned, units_on_base):\n    """Exact per-turn payout; there is no proportional contested-node share."""\n    revenue = sum(value for value, flag in zip(node_value, owned) if flag)\n    return float(revenue - UPKEEP * (UNITS_PER_PLAYER - units_on_base))\n\n\ndef make_plan(obs, distance, hop):\n    n = int(obs["n_nodes"])\n    turn = int(obs.get("turn", 0))\n    remaining = max(0, N_TURNS - turn)\n    base = int(obs["player_base"])\n    enemy_base = int(obs["opponent_base"])\n    values = obs["node_value"]\n    units = obs["player_units"]\n    enemies = obs["opponent_units"]\n    owned = obs["player_owned"]\n    leads = obs["player_lead_turns"]\n\n    # Do not initiate or reinforce a fight. Incoming enemies also disqualify\n    # their destinations, even if they are several turns away.\n    blocked = [bool(enemies[v]) for v in range(n)]\n    for _, destination, count, _ in obs.get("opponent_transits", []):\n        if count > 0:\n            blocked[destination] = True\n\n    targets = {\n        v for v in range(n)\n        if v != base and v != enemy_base and values[v] > 0\n        and not owned[v] and not blocked[v]\n    }\n    available = list(units)\n    plan = []\n\n    def worthwhile(source, target, delay=0):\n        travel = delay + distance[source][target]\n        # From an occupied node a previous lead can shorten the capture.\n        wait = 0 if source == target and delay == 0 and leads[target] else 1\n        capture_offset = max(0, travel - 1) + wait\n        if source == target and delay == 0:\n            capture_offset = 0 if leads[target] else 1\n        revenue_turns = remaining - capture_offset\n        if revenue_turns <= 0:\n            return False\n        # Full remaining expedition cost, including the return journey.\n        # Returning at the last turn is optional, so this is conservative.\n        away_turns = travel + 1 + distance[target][base]\n        if source == target and delay == 0:\n            away_turns = (1 if leads[target] else 2) + distance[target][base]\n        cost = UPKEEP * away_turns\n        return values[target] * revenue_turns > cost + 3.0\n\n    # First finish captures already in progress, retaining exactly one unit.\n    for v in sorted(targets):\n        if available[v] > 0 and worthwhile(v, v):\n            available[v] -= 1\n            targets.remove(v)\n\n    # Account for committed travellers before dispatching new units. No action\n    # is emitted for them: they cannot be redirected until they land.\n    for _, destination, count, arrival in obs.get("player_transits", []):\n        delay = max(0, int(arrival) - turn)\n        for _ in range(min(int(count), n)):\n            choices = [\n                v for v in sorted(targets)\n                if worthwhile(destination, v, delay)\n            ]\n            if not choices:\n                break\n            target = min(choices, key=lambda v: (\n                distance[destination][v], -values[v], v\n            ))\n            targets.remove(target)\n\n    # Reuse away units before paying to launch additional expeditions.\n    sources = sorted(\n        (v for v in range(n) if v != base and available[v] > 0),\n        key=lambda v: (distance[v][base], v)\n    )\n    sources.append(base)\n    for source in sources:\n        while available[source] > 0:\n            choices = [\n                v for v in sorted(targets) if worthwhile(source, v)\n            ]\n            if not choices:\n                break\n            target = min(choices, key=lambda v: (\n                distance[source][v], -values[v], v\n            ))\n            targets.remove(target)\n            available[source] -= 1\n            if source != target and hop[source][target] >= 0:\n                plan.append((source, hop[source][target], 1))\n\n    # Ownership needs no garrison. All unassigned away units return home.\n    for source in range(n):\n        if source != base and available[source] > 0:\n            destination = hop[source][base]\n            if destination >= 0:\n                plan.append((source, destination, available[source]))\n    return plan\n\n\ndef legal_action(plan, obs, lengths):\n    """Aggregate, then validate against start-of-turn units only."""\n    n = int(obs["n_nodes"])\n    available = list(obs["player_units"])\n    totals = {}\n    for source, destination, count in plan:\n        key = (int(source), int(destination))\n        totals[key] = totals.get(key, 0) + int(count)\n\n    action = []\n    for (source, destination), count in sorted(totals.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if source == destination or (source, destination) not in lengths:\n            continue\n        count = min(max(0, count), int(available[source]))\n        if count:\n            action.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_data = None\n\n    def act(self, obs):\n        # All planning state comes from this observation. Only immutable map\n        # information is cached, so skipped turns require no reconciliation.\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs)\n        _, lengths, distance, hop = self.map_data\n        if int(obs.get("turn", 0)) >= N_TURNS:\n            return []\n        plan = make_plan(obs, distance, hop)\n        return legal_action(plan, obs, lengths)\n'
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
